const NumbersBACSSchema = z
  .looseObject({
    account_id: z
      .string()
      .openapi({ description: 'The Plaid account ID associated with the account numbers' }),
    account: z.string().openapi({ description: 'The Bacs account number for the account' }),
    sort_code: z.string().openapi({ description: 'The Bacs sort code for the account' }),
  })
  .openapi({
    title: 'NumbersBACS',
    description:
      'Identifying information for transferring money to or from a UK bank account via Bacs.',
    required: ['account_id', 'account', 'sort_code'],
  })
