const PlaidErrorSchema = z
  .looseObject({
    error_type: PlaidErrorTypeSchema,
    error_code: z
      .string()
      .openapi({ description: 'The particular error code. Safe for programmatic use.' }),
    error_code_reason: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The specific reason for the error code. Currently, reasons are only supported for OAuth-based item errors; the field is omitted otherwise. Safe for programmatic use.\n\nPossible values:\n\n`OAUTH_INVALID_TOKEN`: The user's OAuth connection to this institution has been invalidated.\n\n`OAUTH_CONSENT_EXPIRED`: The user's access consent for this OAuth connection to this institution has expired.\n\n`OAUTH_USER_REVOKED`: The user's OAuth connection to this institution is invalid because the user revoked their connection.",
      }),
    error_message: z
      .string()
      .openapi({
        description:
          'A developer-friendly representation of the error code. This may change over time and is not safe for programmatic use.',
      }),
    display_message: z
      .string()
      .nullable()
      .openapi({
        description:
          'A user-friendly representation of the error code. `null` if the error is not related to user action.\n\nThis may change over time and is not safe for programmatic use.',
      }),
    request_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A unique ID identifying the request, to be used for troubleshooting purposes. This field will be omitted in errors provided by webhooks.',
      }),
    causes: z
      .array(z.any())
      .exactOptional()
      .openapi({
        description:
          'In this product, a request can pertain to more than one Item. If an error is returned for such a request, `causes` will return an array of errors containing a breakdown of these errors on the individual Item level, if any can be identified.\n\n`causes` will be provided for the `error_type` `ASSET_REPORT_ERROR` or `CHECK_REPORT_ERROR`, and for the `USER_ERROR` codes `USER_ITEM_ASSOCIATION_FAILED` and `USER_ITEM_REMOVAL_FAILED`. `causes` will also not be populated inside an error nested within a `warning` object.',
      }),
    status: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The HTTP status code associated with the error. This will only be returned in the response body when the error information is provided via a webhook.',
      }),
    documentation_url: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The URL of a Plaid documentation page with more information about the error',
      }),
    suggested_action: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Suggested steps for resolving the error' }),
    required_account_subtypes: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'A list of the account subtypes that were requested via the `account_filters` parameter in `/link/token/create`. Currently only populated for `NO_ACCOUNTS` errors from Items with `investments_auth` as an enabled product.\n',
      }),
    provided_account_subtypes: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'A list of the account subtypes that were extracted but did not match the requested subtypes via the `account_filters` parameter in `/link/token/create`. Currently only populated for `NO_ACCOUNTS` errors from Items with `investments_auth` as an enabled product.\n',
      }),
  })
  .nullable()
  .openapi({
    description:
      'Errors are identified by `error_code` and categorized by `error_type`. Use these in preference to HTTP status codes to identify and handle specific errors. HTTP status codes are set and provide the broadest categorization of errors: 4xx codes are for developer- or user-related errors, and 5xx codes are for Plaid-related errors, and the status will be 2xx in non-error cases. An Item with a non-`null` error object will only be part of an API response when calling `/item/get` to view Item status. Otherwise, error fields will be `null` if no error has occurred; if an error has occurred, an error code will be returned instead.',
    title: 'Error',
    required: ['error_type', 'error_code', 'error_message', 'display_message'],
  })
  .openapi('PlaidError')

