const AuthVerifyResponseSchema = z
  .looseObject({
    request_id: RequestIDSchema,
    item_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The `item_id` value of the Item created for verification. If numbers data provided is invalid, an Item may not be created.',
      }),
    verification_status: z
      .string()
      .openapi({
        description:
          "Indicates the Item's database verification status. Possible values are:\n\n`database_insights_fail`: The Item's numbers have been verified using Plaid's data sources and have signal for being invalid and/or have no signal for being valid. Typically this indicates that the routing number is invalid, the account number does not match the account number format associated with the routing number, or the account has been reported as closed or frozen. Only returned for Auth Items created via Database Auth.\n\n`database_insights_pass`: The Item's numbers have been verified using Plaid's data sources: the routing and account number match a routing and account number of an account recognized on the Plaid network, and the account is not known by Plaid to be frozen or closed. Only returned for Auth Items created via Database Auth.\n\n`database_insights_pass_with_caution`: The Item's numbers have been verified using Plaid's data sources and have some signal for being valid: the routing and account number were not recognized on the Plaid network, but the routing number is valid and the account number is a potential valid account number for that routing number. Only returned for Auth Items created via Database Auth.\n",
      }),
    verification_insights: AccountVerificationInsightsSchema,
  })
  .openapi({
    description: 'AuthVerifyResponse defines the response schema for `/auth/verify`',
    required: ['request_id', 'verification_status', 'verification_insights'],
  })
  .openapi('AuthVerifyResponse')

