const PersonalFinanceCategorySchema = z
  .looseObject({
    primary: z
      .string()
      .openapi({
        description:
          'A high level category that communicates the broad category of the transaction.',
      }),
    detailed: z
      .string()
      .openapi({
        description:
          "A granular category conveying the transaction's intent. This field can also be used as a unique identifier for the category.",
      }),
    confidence_level: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "A description of how confident we are that the provided categories accurately describe the transaction intent.\n\n`VERY_HIGH`: We are more than 98% confident that this category reflects the intent of the transaction.\n\n`HIGH`: We are more than 90% confident that this category reflects the intent of the transaction.\n\n`MEDIUM`: We are moderately confident that this category reflects the intent of the transaction.\n\n`LOW`: This category may reflect the intent, but there may be other categories that are more accurate.\n\n`UNKNOWN`: We don't know the confidence level for this category.",
      }),
    version: PersonalFinanceCategoryVersionSchema.exactOptional(),
  })
  .nullable()
  .openapi({
    title: 'PersonalFinanceCategory',
    description:
      'Information describing the intent of the transaction. Most relevant for personal finance use cases, but not limited to such use cases.\n\nSee the [taxonomy CSV file](https://plaid.com/documents/pfc-taxonomy-all.csv) for a full list of personal finance categories. If you are migrating to personal finance categories from the legacy categories, also refer to the [migration guide](https://plaid.com/docs/transactions/pfc-migration/).',
    required: ['primary', 'detailed'],
  })
  .openapi('PersonalFinanceCategory')

