const YieldRateTypeSchema = z
  .union([
    z.literal('coupon'),
    z.literal('coupon_equivalent'),
    z.literal('discount'),
    z.literal('yield'),
    z.literal(null),
  ])
  .nullable()
  .openapi({
    title: 'YieldRateType',
    description:
      'The type of rate which indicates how the predicted yield was calculated. It is one of:\n\n`coupon`: the annualized interest rate for securities with a one-year term or longer, such as treasury notes and bonds.\n\n`coupon_equivalent`: the calculated equivalent for the annualized interest rate factoring in the discount rate and time to maturity, for shorter term, non-interest-bearing securities such as treasury bills.\n\n`discount`: the rate at which the present value or cost is discounted from the future value upon maturity, also known as the face value.\n\n`yield`: the total predicted rate of return factoring in both the discount rate and the coupon rate, applicable to securities such as exchange-traded bonds which can both be interest-bearing as well as sold at a discount off their face value.',
  })
  .openapi('YieldRateType')

