const ExternalPaymentScheduleBaseSchema = z
  .looseObject({
    interval: PaymentScheduleIntervalSchema.exactOptional(),
    interval_execution_day: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The day of the interval on which to schedule the payment.\n\nIf the payment interval is weekly, `interval_execution_day` should be an integer from 1 (Monday) to 7 (Sunday).\n\nIf the payment interval is monthly, `interval_execution_day` should be an integer indicating which day of the month to make the payment on. Integers from 1 to 28 can be used to make a payment on that day of the month. Negative integers from -1 to -5 can be used to make a payment relative to the end of the month. To make a payment on the last day of the month, use -1; to make the payment on the second-to-last day, use -2, and so on.',
      }),
    start_date: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          'A date in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format (YYYY-MM-DD). Standing order payments will begin on the first `interval_execution_day` on or after the `start_date`.\n\nIf the first `interval_execution_day` on or after the start date is also the same day that `/payment_initiation/payment/create` was called, the bank *may* make the first payment on that day, but it is not guaranteed to do so.',
      }),
    end_date: z.iso
      .date()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A date in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format (YYYY-MM-DD). Standing order payments will end on the last `interval_execution_day` on or before the `end_date`.\nIf the only `interval_execution_day` between the start date and the end date (inclusive) is also the same day that `/payment_initiation/payment/create` was called, the bank *may* make a payment on that day, but it is not guaranteed to do so.',
      }),
    adjusted_start_date: z.iso
      .date()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The start date sent to the bank after adjusting for holidays or weekends.  Will be provided in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format (YYYY-MM-DD). If the start date did not require adjustment, this field will be `null`.',
      }),
  })
  .nullable()
  .openapi({
    title: 'ExternalPaymentScheduleBase',
    description:
      'The schedule that the payment will be executed on. If a schedule is provided, the payment is automatically set up as a standing order. If no schedule is specified, the payment will be executed only once.',
    required: [],
  })
  .openapi('ExternalPaymentScheduleBase')

const ExternalPaymentScheduleRequestSchema = ExternalPaymentScheduleBaseSchema.and(z.object({}))
