const WalletTransactionIdempotencyKeySchema = z
  .string()
  .min(1)
  .max(128)
  .openapi({
    title: 'WalletTransactionIdempotencyKey',
    description:
      'A random key provided by the client, per unique wallet transaction. Maximum of 128 characters.\n\nThe API supports idempotency for safely retrying requests without accidentally performing the same operation twice. If a request to execute a wallet transaction fails due to a network connection error, then after a minimum delay of one minute, you can retry the request with the same idempotency key to guarantee that only a single wallet transaction is created. If the request was successfully processed, it will prevent any transaction that uses the same idempotency key, and was received within 48 hours of the first request, from being processed.',
  })
  .openapi('WalletTransactionIdempotencyKey')

