const PaymentInitiationConsentCreateRequestSchema = z
  .object({
    client_id: APIClientIDSchema.exactOptional(),
    secret: APISecretSchema.exactOptional(),
    recipient_id: z
      .string()
      .openapi({
        description:
          'The ID of the recipient the payment consent is for. The created consent can be used to transfer funds to this recipient only.',
      }),
    user_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The `user_id` of the end user the payment consent is for, as returned by [`/user/create`](https://plaid.com/docs/api/users/#usercreate). The user must have a `name` and either an email address or a phone number. Payments created from this consent inherit this `user_id`. Required for new integrations.',
      }),
    reference: z
      .string()
      .min(1)
      .max(18)
      .openapi({
        description:
          'A reference for the payment consent. This must be a string of at most 18 characters containing only letters, numbers, and spaces.',
      }),
    scopes: z
      .array(PaymentInitiationConsentScopeSchema)
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ deprecated: true, description: 'An array of payment consent scopes.' }),
    type: PaymentInitiationConsentTypeSchema.exactOptional(),
    constraints: PaymentInitiationConsentConstraintsSchema,
    options: ExternalPaymentInitiationConsentOptionsSchema.exactOptional(),
    payer_details: PaymentInitiationConsentPayerDetailsSchema.exactOptional(),
  })
  .openapi({
    description:
      'PaymentInitiationConsentCreateRequest defines the request schema for `/payment_initiation/consent/create`',
    required: ['recipient_id', 'reference', 'constraints'],
  })
  .openapi('PaymentInitiationConsentCreateRequest')

const PaymentInitiationConsentStatusSchema = z
  .enum(['UNAUTHORISED', 'AUTHORISED', 'REVOKED', 'REJECTED', 'EXPIRED'])
  .openapi({
    description:
      'The status of the payment consent.\n\n`UNAUTHORISED`: Consent created, but requires user authorisation.\n\n`REJECTED`: Consent authorisation was rejected by the bank.\n\n`AUTHORISED`: Consent is active and ready to be used.\n\n`REVOKED`: Consent has been revoked and can no longer be used.\n\n`EXPIRED`: Consent is no longer valid.',
  })
  .openapi('PaymentInitiationConsentStatus')

