const ConsentPaymentIdempotencyKeySchema = z
  .string()
  .min(1)
  .max(128)
  .openapi({
    title: 'ConsentPaymentIdempotencyKey',
    description:
      'A random key provided by the client, per unique consent payment. Maximum of 128 characters.\n\nThe API supports idempotency for safely retrying requests without accidentally performing the same operation twice. If a request to execute a consent payment fails due to a network connection error, you can retry the request with the same idempotency key to guarantee that only a single payment is created. If the request was successfully processed, it will prevent any payment that uses the same idempotency key, and was received within 48 hours of the first request, from being processed.',
  })
  .openapi('ConsentPaymentIdempotencyKey')

const PaymentInitiationConsentProcessingModeSchema = z
  .enum(['ASYNC', 'IMMEDIATE'])
  .openapi({
    title: 'PaymentInitiationConsentProcessingMode',
    description:
      'Decides the mode under which the payment processing should be performed, using `IMMEDIATE` as default.\n\n`IMMEDIATE`: Will immediately execute the payment, waiting for a response from the ASPSP before returning the result of the payment initiation. This is ideal for user-present flows.\n\n `ASYNC`: Will accept a payment execution request and schedule it for processing, immediately returning the new `payment_id`. Listen for webhooks to obtain real-time updates on the payment status. This is ideal for non user-present flows.',
  })
  .openapi('PaymentInitiationConsentProcessingMode')

const PaymentInitiationConsentPaymentExecuteRequestSchema = z
  .object({
    client_id: APIClientIDSchema.exactOptional(),
    secret: APISecretSchema.exactOptional(),
    consent_id: z.string().openapi({ description: 'The consent ID.' }),
    amount: PaymentAmountSchema,
    idempotency_key: ConsentPaymentIdempotencyKeySchema,
    reference: z
      .string()
      .min(1)
      .max(18)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "A reference for the payment. This must be a string of at most 18 characters containing only letters, numbers, and spaces (since not all institutions support them).\nIf not provided, Plaid will automatically fall back to the reference from consent. In order to track settlement via Payment Confirmation, each payment must have a unique reference. If the reference provided through the API is not unique, Plaid will adjust it.\nSome institutions may limit the reference to less than 18 characters. If necessary, Plaid will adjust the reference by truncating it to fit the institution's requirements.\nBoth the originally provided and automatically adjusted references (if any) can be found in the `reference` and `adjusted_reference` fields, respectively.",
      }),
    scope: PaymentInitiationConsentScopeSchema.and(
      z
        .string()
        .nullable()
        .openapi({
          description:
            'Deprecated, payments will be executed within the type of the consent.\n\nA scope of the payment. Must be one of the scopes mentioned in the consent.\nOptional if the appropriate consent has only one scope defined, required otherwise.',
        }),
    )
      .exactOptional()
      .openapi({ deprecated: true }),
    processing_mode: PaymentInitiationConsentProcessingModeSchema.exactOptional(),
  })
  .openapi({
    description:
      'PaymentInitiationConsentPaymentExecuteRequest defines the request schema for `/payment_initiation/consent/payment/execute`',
    required: ['consent_id', 'amount', 'idempotency_key'],
  })
  .openapi('PaymentInitiationConsentPaymentExecuteRequest')

