const MFASchema = z
  .looseObject({
    type: z
      .string()
      .openapi({
        description:
          'Possible values are `device`, `selections`, or `questions`.\n\nIf value is `device`, the MFA answer is `1234`.\n\nIf value is `selections`, the MFA answer is always the first option.\n\nIf value is `questions`, the MFA answer is  `answer_<i>_<j>` for the j-th question in the i-th round, starting from 0. For example, the answer to the first question in the second round is `answer_1_0`.',
      }),
    question_rounds: z
      .number()
      .exactOptional()
      .openapi({
        description: 'Number of rounds of questions. Required if value of `type` is `questions`. ',
      }),
    questions_per_round: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Number of questions per round. Required if value of `type` is `questions`. If value of type is `selections`, default value is 2.',
      }),
    selection_rounds: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Number of rounds of selections, used if `type` is `selections`. Defaults to 1.',
      }),
    selections_per_question: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Number of available answers per question, used if `type` is `selections`. Defaults to 2.\n',
      }),
  })
  .openapi({
    title: 'MFA',
    required: ['type'],
    description: 'Specifies the multi-factor authentication settings to use with this test account',
  })
  .openapi('MFA')

const UserCustomPasswordSchema = z
  .looseObject({
    version: z
      .int()
      .min(1)
      .max(2)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The version of the password schema to use, sent as a number. Possible values are `1` or `2`. The default value is `2`. You should only specify `1` if you know it is necessary for your test suite.',
      }),
    seed: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "A seed, in the form of a string, that will be used to randomly generate account and transaction data, if this data is not specified using the `override_accounts` argument. If no seed is specified, the randomly generated data will be different each time.\n\nNote that transactions data is generated relative to the Item's creation date. Different Items created on different dates with the same seed for transactions data will have different dates for the transactions. The number of days between each transaction and the Item creation will remain constant. For example, an Item created on December 15 might show a transaction on December 14. An Item created on December 20, using the same seed, would show that same transaction occurring on December 19.",
      }),
    roll_dates_forward: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "When `true`, every date in this configuration is shifted at Item creation so that the most recent activity date falls on the day the Item is created, keeping the spacing between dates. Activity dates are transaction and investment transaction dates, pay period end dates and pay days, holding `institution_price_as_of` dates, and a loan's `last_payment_date` or `last_statement_issue_date`. Scheduled loan dates such as `origination_date`, `maturity_date`, and `next_payment_due_date` move by the same amount but are never the anchor. This lets a saved configuration keep producing recent data without being edited.\n\nA `date_posted` later than its `date_transacted` stays later, so the most recent transaction can still be pending. Dates are UTC calendar dates. The shift happens once, when the Item is created; the Item keeps the shifted dates afterwards. Defaults to `false`.",
      }),
    override_accounts: z
      .array(OverrideAccountsSchema)
      .exactOptional()
      .openapi({
        description:
          'An array of account overrides to configure the accounts for the Item. By default, if no override is specified, transactions and account data will be randomly generated based on the account type and subtype, and other products will have fixed or empty data.',
      }),
    mfa: MFASchema.exactOptional(),
    recaptcha: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'You may trigger a reCAPTCHA in Plaid Link in the Sandbox environment by using the recaptcha field. Possible values are `good` or `bad`. A value of `good` will result in successful Item creation and `bad` will result in a `RECAPTCHA_BAD` error to simulate a failed reCAPTCHA. Both values require the reCAPTCHA to be manually solved within Plaid Link.',
      }),
    force_error: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'An error code to force on Item creation. Possible values are:\n\n`"INSTITUTION_NOT_RESPONDING"`\n`"INSTITUTION_NO_LONGER_SUPPORTED"`\n`"INVALID_CREDENTIALS"`\n`"INVALID_MFA"`\n`"ITEM_LOCKED"`\n`"ITEM_LOGIN_REQUIRED"`\n`"ITEM_NOT_SUPPORTED"`\n`"INVALID_LINK_TOKEN"`\n`"MFA_NOT_SUPPORTED"`\n`"NO_ACCOUNTS"`\n`"PLAID_ERROR"`\n`"USER_INPUT_TIMEOUT"`\n`"USER_SETUP_REQUIRED"`',
      }),
  })
  .openapi({
    title: 'UserCustomPassword',
    description:
      'Custom test accounts are configured with a JSON configuration object formulated according to the schema below. All top level fields are optional. Sending an empty object as a configuration will result in an account configured with random balances and transaction history.',
    'x-examples': {},
    required: [],
  })
  .openapi('UserCustomPassword')

