const WalletTransactionFailureReasonSchema = z
  .enum([
    'EXTERNAL_SYSTEM',
    'EXPIRED',
    'CANCELLED',
    'INVALID',
    'ACCOUNT_INVALID',
    'AUTHENTICATION_FAILED',
    'UNKNOWN',
  ])
  .nullable()
  .openapi({
    description:
      'The error code of a failed transaction. Error codes include:\n\n`EXTERNAL_SYSTEM`: The transaction was declined by an external system.\n\n`EXPIRED`: The transaction request has expired.\n\n`CANCELLED`: The transaction request was rescinded.\n\n`INVALID`: The transaction did not meet certain criteria, such as an inactive account or no valid counterparty, etc.\n\n`ACCOUNT_INVALID`: The transaction could not be processed because the wallet account is invalid or inactive.\n\n`AUTHENTICATION_FAILED`: The transaction could not be processed because authentication with the wallet provider failed.\n\n`UNKNOWN`: The transaction was unsuccessful, but the exact cause is unknown.',
  })
  .openapi('WalletTransactionFailureReason')

