const UserPermissionRevokedWebhookSchema = z
  .looseObject({
    webhook_type: z.string().openapi({ description: '`ITEM`' }),
    webhook_code: z.string().openapi({ description: '`USER_PERMISSION_REVOKED`' }),
    item_id: ItemIdSchema,
    user_id: UserIdSchema.exactOptional(),
    error: PlaidErrorSchema.exactOptional(),
    environment: WebhookEnvironmentValuesSchema,
  })
  .openapi({
    title: 'UserPermissionRevokedWebhook',
    description:
      "The `USER_PERMISSION_REVOKED` webhook may be fired when an end user has revoked the permission that they previously granted to access an Item. If the end user revoked their permissions through Plaid (such as via the Plaid Portal or by contacting Plaid support), the webhook will fire. If the end user revoked their permissions directly through the institution, this webhook may not always fire, since some institutions' consent portals do not trigger this webhook. To attempt to restore the Item, it can be sent through [update mode](https://plaid.com/docs/link/update-mode). Depending on the exact process the end user used to revoke permissions, it may not be possible to launch update mode for the Item. If you encounter an error when attempting to create a Link token for update mode on an Item with revoked permissions, create a fresh Link token for the user.\n\nNote that when working with tokenized account numbers with Auth or Transfer, the account number provided by Plaid will no longer work for creating transfers once user permission has been revoked, except for US Bank Items.",
    'x-examples': {
      'example-1': {
        webhook_type: 'ITEM',
        webhook_code: 'USER_PERMISSION_REVOKED',
        error: {
          error_code: 'USER_PERMISSION_REVOKED',
          error_message:
            'the holder of this account has revoked their permission for your application to access it',
          display_message: null,
          error_type: 'ITEM_ERROR',
          status: 400,
        },
        item_id: 'gAXlMgVEw5uEGoQnnXZ6tn9E7Mn3LBc4PJVKZ',
        user_id: 'usr_9nSp2KuZ2x4JDw',
        environment: 'production',
      },
    },
    required: ['webhook_type', 'webhook_code', 'item_id', 'environment'],
  })
  .openapi('UserPermissionRevokedWebhook')

