const TransferRecurringStatusSchema = z
  .enum(['active', 'cancelled', 'expired'])
  .openapi({
    title: 'TransferRecurringStatus',
    description:
      'The status of the recurring transfer.\n\n`active`: The recurring transfer is currently active.\n\n`cancelled`: The recurring transfer was cancelled by the client or Plaid.\n\n`expired`: The recurring transfer has completed all originations according to its recurring schedule.',
  })
  .openapi('TransferRecurringStatus')

const TransferRecurringNetworkSchema = z
  .enum(['ach', 'same-day-ach', 'rtp'])
  .openapi({
    title: 'TransferRecurringNetwork',
    description: 'Networks eligible for recurring transfers.',
  })
