const SweepStatusSchema = z
  .union([
    z.literal('pending'),
    z.literal('posted'),
    z.literal('settled'),
    z.literal('funds_available'),
    z.literal('returned'),
    z.literal('failed'),
    z.literal(null),
  ])
  .nullable()
  .openapi({
    title: 'SweepStatus',
    description:
      'The status of a sweep transfer\n\n`"pending"` - The sweep is currently pending\n\n`"posted"` - The sweep has been posted\n\n`"settled"` - The sweep has settled. This is the terminal state of a successful credit sweep.\n\n`"returned"` - The sweep has been returned. This is the terminal state of a returned sweep. Returns of a sweep are extremely rare, since sweeps are money movement between your own bank account and your own Ledger.\n\n`"funds_available"` - Funds from the sweep have been released from hold and applied to the ledger\'s available balance. (Only applicable to deposits.) This is the terminal state of a successful deposit sweep.\n\n`"failed"` - The sweep has failed. This is the terminal state of a failed sweep.',
  })
  .openapi('SweepStatus')

const SweepTriggerSchema = z
  .enum(['manual', 'incoming', 'balance_threshold', 'automatic_aggregate'])
