const CreditDocumentTypeSchema = z
  .string()
  .nullable()
  .openapi({
    title: 'CreditDocumentType',
    description:
      'The type of document.\n\n`PAYSTUB`: A paystub.\n\n`BANK_STATEMENT`: A bank statement.\n\n`US_TAX_W2`: A W-2 wage and tax statement provided by a US employer reflecting wages earned by the employee.\n\n`US_TAX_1099_MISC`: A 1099-MISC tax form reporting miscellaneous income.\n\n`US_TAX_1099_K`: A 1099-K tax form reporting payment card and third-party network transactions.\n\n`US_STUDENT_I20`: A Certificate of Eligibility for Nonimmigrant Student Status (Form I-20) issued by a US school.\n\n`US_MILITARY_ERAS`: An electronic Retirement Account Statement (eRAS) issued by the US military.\n\n`US_MILITARY_LES`: A Leave and Earnings Statement (LES) issued by the US military.\n\n`US_MILITARY_CLES`: A Civilian Leave and Earnings Statement (CLES) issued by the US military.\n\n`GIG`: Used to indicate that the income is related to gig work. Does not necessarily correspond to a specific document type.\n\n`PLAID_GENERATED_PAYSTUB_PDF`: Used to indicate that the PDF for the paystub was generated by Plaid.\n\n`NONE`: Used to indicate that there is no underlying document for the data.\n\n`UNKNOWN`: Document type could not be determined.',
    'x-override-enum-values-shown': [
      'UNKNOWN',
      'PAYSTUB',
      'BANK_STATEMENT',
      'US_TAX_W2',
      'US_TAX_1099_MISC',
      'US_TAX_1099_K',
      'US_STUDENT_I20',
      'US_MILITARY_ERAS',
      'US_MILITARY_LES',
      'US_MILITARY_CLES',
      'GIG',
      'PLAID_GENERATED_PAYSTUB_PDF',
      'NONE',
    ],
  })
  .openapi('CreditDocumentType')

const CreditDocumentMetadataSchema = z
  .looseObject({
    name: z.string().openapi({ description: 'The name of the document.' }),
    document_type: CreditDocumentTypeSchema,
    download_url: z
      .string()
      .nullable()
      .openapi({
        description:
          'Signed URL to retrieve the document(s). The payload will be a .zip file containing the document(s).\n\nFor Payroll Income, the file type of the documents will always be PDF, and the documents may not be available, in which case the field will be `null`. If you would like Plaid to generate a PDF if the original is not available, contact your account manager. [Example generated pay stub](https://plaid.com/documents/plaid-generated-mock-paystub.pdf).\n\nFor Document Income, this field will not be `null`, and the file type of the underlying document(s) will be the original file type uploaded by the user. For more details on available file types, see the [Document Income](https://plaid.com/docs/income/document-income) documentation.\n\nThis download URL can only be used once and expires after two minutes. To generate a new download URL, call `/credit/payroll_income/get` again.',
      }),
    status: z
      .string()
      .nullable()
      .openapi({
        description:
          'The processing status of the document.\n\n`PROCESSING_COMPLETE`: The document was successfully processed.\n\n`DOCUMENT_ERROR`: The document could not be processed. Possible causes include: The document was an unacceptable document type such as an offer letter or bank statement, the document image was cropped or blurry, or the document was corrupted.\n\n`UNKNOWN` or `null`: An internal error occurred. If this happens repeatedly, contact support or your Plaid account manager.',
        'x-override-enum-values-shown': ['UNKNOWN', 'PROCESSING_COMPLETE', 'DOCUMENT_ERROR', null],
      }),
    page_count: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The number of pages of the uploaded document (if available).' }),
    error_message: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The reason why a failure occurred during document processing (if available).',
      }),
  })
  .openapi({
    title: 'CreditDocumentMetadata',
    description: 'Object representing metadata pertaining to the document.',
    required: ['name', 'document_type', 'download_url', 'status'],
  })
  .openapi('CreditDocumentMetadata')

