          'FONT',
          'MASKING',
          'OVERLAID_TEXT',
          'EDITED_TEXT',
          'TEXT_COMPRESSION',
          'ADDRESS_FORMAT_ANOMALY',
          'DATE_FORMAT_ANOMALY',
