const WalletTransactionRelationSchema = z
  .looseObject({
    id: z.string().exactOptional().openapi({ description: 'The ID of the related transaction.' }),
    type: z
      .enum(['PAYOUT', 'RETURN', 'REFUND', 'FUNDS_SWEEP'])
      .exactOptional()
      .openapi({ description: 'The type of the transaction.' }),
  })
  .openapi({
    title: 'WalletTransactionRelation',
    description:
      'Transactions are related when they have a logical connection.\n\nFor example, a `PAYOUT` transaction can be returned by the sender, creating a `RETURN` transaction. Each `PAYOUT` transaction can have at most one corresponding `RETURN` transaction in case of reversal.\n\nThese relationships are bi-directional, meaning that both entities have references to each other. For instance, when a transaction of type RETURN occurs, it is linked to the original transaction being returned. Likewise, the original transaction has a reference back to the RETURN transaction that represents the return.\n\nThis field is only populated for transactions of type `RETURN`, `FUNDS_SWEEP`, `REFUND` and `PAYOUT`.\n\nThe relationship between a `PIS_PAY_IN` payment and its corresponding `REFUND` transactions is only available through the `refund_ids` property in the payment object. See [`/payment_initiation/payment/get`](https://plaid.com/docs/api/products/payment-initiation/#payment_initiation-payment-get-response-refund-ids).',
    required: [],
  })
  .openapi('WalletTransactionRelation')

const WalletTransactionPayeeVerificationStatusSchema = z
  .enum(['FULL_MATCH', 'PARTIAL_MATCH', 'NO_MATCH', 'ERROR', 'CHECK_NOT_POSSIBLE'])
  .nullable()
  .openapi({
    description:
      'Result of payee verification check for EUR and GBP payouts. Payee verification checks whether the payee name provided matches the account holder name at the destination institution.\n\n`FULL_MATCH`: The payee name fully matches the account holder.\n\n`PARTIAL_MATCH`: The payee name partially matches the account holder.\n\n`NO_MATCH`: The payee name does not match the account holder.\n\n`ERROR`: An error occurred during payee verification.\n\n`CHECK_NOT_POSSIBLE`: Payee verification could not be performed.\n\nThis field is only populated for applicable EUR and GBP payout transactions and will be `null` for other transaction types.',
  })
  .openapi('WalletTransactionPayeeVerificationStatus')

