const BetaPartnerCustomerV1CreateRequestSchema = z
  .object({
    client_id: APIClientIDSchema.exactOptional(),
    secret: APISecretSchema.exactOptional(),
    company_name: z
      .string()
      .openapi({
        description:
          'The company name of the end customer being created. This will be used to display the end customer in the Plaid Dashboard. It will not be shown to end users.',
      }),
    is_diligence_attested: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Denotes whether or not the partner has completed attestation of diligence for the end customer to be created.',
      }),
    products: z
      .array(ProductsSchema)
      .exactOptional()
      .openapi({
        description:
          'The products to be enabled for the end customer. If empty or `null`, this field will default to the products enabled for the reseller at the time this endpoint is called.',
      }),
    create_link_customization: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "If `true`, the end customer's default Link customization will be set to match the partner's. You can always change the end customer's Link customization in the Plaid Dashboard. See the [Link Customization docs](https://plaid.com/docs/link/customization/) for more information. If you require the ability to programmatically create end customers using multiple different Link customization profiles, contact your Plaid account manager for assistance.\n\nImportant: Data Transparency Messaging (DTM) use cases will not be copied to the end customer's Link customization unless the **Publish changes** button is clicked after the use cases are applied. Link will not work in Production unless the end customer's DTM use cases are configured. For more details, see [Data Transparency Messaging](https://plaid.com/docs/link/data-transparency-messaging-migration-guide/).",
      }),
    logo: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Base64-encoded representation of the end customer's logo. Must be a PNG of size 1024x1024 under 4MB. The logo will be shared with financial institutions and shown to the end user during Link flows. A logo is required if `create_link_customization` is `true`. If `create_link_customization` is `false` and the logo is omitted, the partner's logo will be used if one exists, otherwise a stock logo will be used.",
      }),
    legal_entity_name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The end customer's legal name. This will be shared with financial institutions as part of the OAuth registration process. It will not be shown to end users.",
      }),
    website: z.string().openapi({ description: "The end customer's website." }),
    application_name: z
      .string()
      .openapi({
        description:
          "The name of the end customer's application. This will be shown to end users when they go through the Plaid Link flow. The application name must be unique and cannot match the name of another application already registered with Plaid.",
      }),
    technical_contact: PartnerEndCustomerTechnicalContactSchema.exactOptional(),
    billing_contact: PartnerEndCustomerBillingContactSchema.exactOptional(),
    customer_support_info: PartnerEndCustomerCustomerSupportInfoSchema,
    address: PartnerEndCustomerAddressSchema,
    redirect_uris: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          "A list of URIs indicating the destination(s) where a user can be forwarded after completing the Link flow; used to support OAuth authentication flows when launching Link in the browser or another app. URIs should not contain any query parameters. When used in Production, URIs must use https. To modify redirect URIs for an end customer after creating them, go to the end customer's [API page](https://dashboard.plaid.com/team/api) in the Dashboard.",
      }),
    bank_addendum_acceptance: PartnerEndCustomerBankAddendumAcceptanceSchema.exactOptional(),
    questionnaires: PartnerEndCustomerQuestionnairesSchema.exactOptional(),
  })
  .openapi({
    description: 'Request schema for `/beta/partner/customer/v1/create`.',
    required: ['company_name', 'website', 'application_name', 'address', 'customer_support_info'],
  })
  .openapi('BetaPartnerCustomerV1CreateRequest')

const PartnerEndCustomerProductStatusesSchema = z
  .looseObject({})
