const UserAccountRevokedWebhookSchema = z
  .looseObject({
    webhook_type: z.string().openapi({ description: '`ITEM`' }),
    webhook_code: z.string().openapi({ description: '`USER_ACCOUNT_REVOKED`' }),
    item_id: ItemIdSchema,
    user_id: UserIdSchema.exactOptional(),
    account_id: z
      .string()
      .openapi({ description: 'The external account ID of the affected account' }),
    environment: WebhookEnvironmentValuesSchema,
  })
  .openapi({
    title: 'UserAccountRevokedWebhook',
    description:
      "The `USER_ACCOUNT_REVOKED` webhook is fired when an end user has revoked access to their account on the Data Provider's portal. This webhook is currently sent only for Chase, PNC, and Truist Items, but may be sent in the future for other financial institutions that allow account-level permissions revocation through their portals. Upon receiving this webhook, it is recommended to delete any Plaid-derived data you have stored that is associated with the revoked account.\n\nIf you are using Auth and receive this webhook, this webhook indicates that the TAN associated with the revoked account is no longer valid and cannot be used to create new transfers. You should not create new ACH transfers for the account that was revoked until access has been re-granted.\n\nYou can request the user to re-grant access to their account by sending them through [update mode](https://plaid.com/docs/link/update-mode). Alternatively, they may re-grant access directly through the Data Provider's portal.\n\nAfter the user has re-granted access, Auth customers should call the auth endpoint again to obtain the new TAN.",
    'x-examples': {
      'example-1': {
        webhook_type: 'ITEM',
        webhook_code: 'USER_ACCOUNT_REVOKED',
        item_id: 'gAXlMgVEw5uEGoQnnXZ6tn9E7Mn3LBc4PJVKZ',
        account_id: 'BxBXxLj1m4HMXBm9WZJyUg9XLd4rKEhw8Pb1J',
        user_id: 'usr_9nSp2KuZ2x4JDw',
        environment: 'production',
      },
    },
    required: ['webhook_type', 'webhook_code', 'item_id', 'account_id', 'environment'],
  })
  .openapi('UserAccountRevokedWebhook')

