const AccountAssetsSchema = z
  .looseObject({
    account_id: z
      .string()
      .openapi({
        description:
          "Plaid's unique identifier for the account. This value will not change unless Plaid can't reconcile the account with the data returned by the financial institution. This may occur, for example, when the name of the account changes. If this happens a new `account_id` will be assigned to the account.\n\nThe `account_id` can also change if the `access_token` is deleted and the same credentials that were used to generate that `access_token` are used to generate a new `access_token` on a later date. In that case, the new `account_id` will be different from the old `account_id`.\n\nIf an account with a specific `account_id` disappears instead of changing, the account is likely closed. Closed accounts are not returned by the Plaid API.\n\nLike all Plaid identifiers, the `account_id` is case sensitive.",
      }),
    balances: AssetReportAccountBalanceSchema,
    mask: z
      .string()
      .nullable()
      .openapi({
        description:
          "The last 2-4 alphanumeric characters of an account's official account number. Note that the mask may be non-unique between an Item's accounts, and it may also not match the mask that the bank displays to the user.",
      }),
    name: z
      .string()
      .openapi({
        description:
          'The name of the account, either assigned by the user or by the financial institution itself',
      }),
    official_name: z
      .string()
      .nullable()
      .openapi({
        description: 'The official name of the account as given by the financial institution',
      }),
    type: AccountTypeSchema,
    subtype: AccountSubtypeSchema,
    verification_status: z
      .enum([
        'automatically_verified',
        'pending_automatic_verification',
        'pending_manual_verification',
        'manually_verified',
        'verification_expired',
        'verification_failed',
        'database_matched',
      ])
      .exactOptional()
      .openapi({
        'x-hidden-from-docs': true,
        description:
          "The current verification status of an Auth Item initiated through Automated or Manual micro-deposits.  Returned for Auth Items only.\n\n`pending_automatic_verification`: The Item is pending automatic verification.\n\n`pending_manual_verification`: The Item is pending manual micro-deposit verification. Items remain in this state until the user successfully verifies the micro-deposit.\n\n`automatically_verified`: The Item has successfully been automatically verified.\n\n`manually_verified`: The Item has successfully been manually verified.\n\n`verification_expired`: Plaid was unable to automatically verify the deposit within 7 calendar days and will no longer attempt to validate the Item. Users may retry by submitting their information again through Link.\n\n`verification_failed`: The Item failed manual micro-deposit verification because the user exhausted all 3 verification attempts. Users may retry by submitting their information again through Link.\n\n`database_matched`: (deprecated) The Item has successfully been verified using Plaid's data sources. Only returned for Auth Items created via Database Match.",
      }),
    persistent_account_id: z
      .string()
      .exactOptional()
      .openapi({
        'x-hidden-from-docs': true,
        description:
          'A unique and persistent identifier for accounts that can be used to trace multiple instances of the same account across different Items for depository accounts. This is currently an opt-in field and only supported for Chase Items.',
      }),
    days_available: z
      .number()
      .openapi({
        description:
          'The duration of transaction history available within this report for this Item, typically defined as the time since the date of the earliest transaction in that account.',
      }),
    transactions: z
      .array(AssetReportTransactionSchema)
      .openapi({ description: 'Transaction history associated with the account.' }),
    investments: AssetReportInvestmentsSchema.exactOptional(),
    owners: z
      .array(OwnerSchema)
      .openapi({
        description:
          'Data returned by the financial institution about the account owner or owners. For business accounts, the name reported may be either the name of the individual or the name of the business, depending on the institution. Multiple owners on a single account will be represented in the same `owner` object, not in multiple owner objects within the array. In API versions 2018-05-22 and earlier, the `owners` object is not returned, and instead identity information is returned in the top level `identity` object. For more details, see [Plaid API versioning](https://plaid.com/docs/api/versioning/#version-2019-05-29)',
      }),
    ownership_type: OwnershipTypeSchema.exactOptional(),
    historical_balances: z
      .array(HistoricalBalanceSchema)
      .openapi({
        description:
          'Calculated data about the historical balances on the account.\n\nAvailable for `credit` and `depository` type accounts.',
      }),
    account_insights: AccountInsightsSchema.exactOptional(),
  })
  .openapi({
    title: 'AccountAssets',
    description: 'Asset information about an account',
    required: [
      'account_id',
      'balances',
      'mask',
      'name',
      'official_name',
      'type',
      'subtype',
      'days_available',
      'transactions',
      'owners',
      'historical_balances',
    ],
  })
  .openapi('AccountAssets')

