const BaseReportAccountSchema = z
  .looseObject({
    account_id: z
      .string()
      .openapi({
        description:
          "Plaid's unique identifier for the account. This value will not change unless Plaid can't reconcile the account with the data returned by the financial institution. This may occur, for example, when the name of the account changes. If this happens a new `account_id` will be assigned to the account.\n\nIf an account with a specific `account_id` disappears instead of changing, the account is likely closed. Closed accounts are not returned by the Plaid API.\n\nLike all Plaid identifiers, the `account_id` is case sensitive.",
      }),
    balances: BaseReportAccountBalancesSchema,
    consumer_disputes: z
      .array(ConsumerDisputeSchema)
      .openapi({
        description:
          'The information about previously submitted valid dispute statements by the consumer',
      }),
    mask: z
      .string()
      .nullable()
      .openapi({
        description:
          "The last 2-4 alphanumeric characters of an account's official account number. Note that the mask may be non-unique between an Item's accounts, and it may also not match the mask that the bank displays to the user.",
      }),
    metadata: BaseReportAccountMetadataSchema,
    name: z
      .string()
      .openapi({
        description:
          'The name of the account, either assigned by the user or by the financial institution itself',
      }),
    official_name: z
      .string()
      .nullable()
      .openapi({
        description: 'The official name of the account as given by the financial institution',
      }),
    type: AccountTypeSchema,
    subtype: AccountSubtypeSchema,
    days_available: z
      .number()
      .openapi({
        description:
          'The duration of transaction history available within this report for this Item, typically defined as the time since the date of the earliest transaction in that account.',
      }),
    transactions: z
      .array(BaseReportTransactionSchema)
      .openapi({
        description:
          'Transaction history associated with the account. Transaction history returned by endpoints such as `/transactions/get` or `/investments/transactions/get` will be returned in the top-level `transactions` field instead. Some transactions may have their details masked in accordance with the FCRA. These will appear with a `credit_category` of `MASKED_TRANSACTION_CATEGORY`.',
      }),
    owners: z
      .array(OwnerSchema)
      .openapi({
        description:
          'Data returned by the financial institution about the account owner or owners. For business accounts, the name reported may be either the name of the individual or the name of the business, depending on the institution. Multiple owners on a single account will be represented in the same `owner` object, not in multiple owner objects within the array. This array can also be empty if no owners are found.',
      }),
    ownership_type: OwnershipTypeSchema,
    historical_balances: z
      .array(BaseReportHistoricalBalanceSchema)
      .exactOptional()
      .openapi({
        'x-hidden-from-docs': true,
        description:
          'Calculated data about the historical balances on the account. Currently not supported by `brokerage` or `investment` accounts.',
      }),
    account_insights: BaseReportAccountInsightsSchema.exactOptional(),
    attributes: BaseReportAttributesSchema.exactOptional(),
  })
  .openapi({
    title: 'BaseReportAccount',
    description: 'Base Report information about an account',
    required: [
      'account_id',
      'balances',
      'consumer_disputes',
      'mask',
      'metadata',
      'name',
      'official_name',
      'type',
      'subtype',
      'days_available',
      'transactions',
      'owners',
      'ownership_type',
    ],
  })
  .openapi('BaseReportAccount')

