const PhysicalDocumentCategorySchema = z
  .enum([
    'drivers_license',
    'id_card',
    'passport',
    'residence_permit_card',
    'resident_card',
    'visa',
  ])
  .openapi({
    description:
      "The type of identity document detected in the images provided. Will always be one of the following values:\n\n  `drivers_license` - A driver's license issued by the associated country, establishing identity without any guarantee as to citizenship, and granting driving privileges\n\n  `id_card` - A general national identification card, distinct from driver's licenses as it only establishes identity\n\n  `passport` - A travel passport issued by the associated country for one of its citizens\n\n  `residence_permit_card` - An identity document issued by the associated country permitting a foreign citizen to <em>temporarily</em> reside there\n\n  `resident_card` - An identity document issued by the associated country permitting a foreign citizen to <em>permanently</em> reside there\n\n  `visa` - An identity document issued by the associated country permitting a foreign citizen entry for a short duration and for a specific purpose, typically no longer than 6 months\n\nNote: This value may be different from the ID type that the user selects within Link. For example, if they select \"Driver's License\" but then submit a picture of a passport, this field will say `passport`",
    example: 'drivers_license',
  })
  .openapi('PhysicalDocumentCategory')

