const EntityWatchlistScreeningProgramNameSchema = z
  .string()
  .openapi({
    title: 'EntityWatchlistScreeningProgramName',
    example: 'Sample Program',
    description:
      'A name for the entity program to define its purpose. For example, "High Risk Organizations" or "Applicants".',
  })
  .openapi('EntityWatchlistScreeningProgramName')

const ProgramNameSensitivitySchema = z
  .enum(['coarse', 'balanced', 'strict', 'exact'])
  .openapi({
    example: 'balanced',
    description:
      'The valid name matching sensitivity configurations for a screening program. Note that while certain matching techniques may be more prevalent on less strict settings, all matching algorithms are enabled for every sensitivity.\n\n`coarse` - See more potential matches. This sensitivity will see more broad phonetic matches across alphabets that make missing a potential hit very unlikely. This setting is noisier and will require more manual review.\n\n`balanced` - A good default for most companies. This sensitivity is balanced to show high quality hits with reduced noise.\n\n`strict` - Aggressive false positive reduction. This sensitivity will require names to be more similar than `coarse` and `balanced` settings, relying less on phonetics, while still accounting for character transpositions, missing tokens, and other common permutations.\n\n`exact` - Matches must be nearly exact. This sensitivity will only show hits with exact or nearly exact name matches with only basic correction such as extraneous symbols and capitalization. This setting is generally not recommended unless you have a very specific use case.',
    title: 'ProgramNameSensitivity',
  })
  .openapi('ProgramNameSensitivity')

const SourceSchema = z
  .enum(['dashboard', 'link', 'api', 'system', 'retro'])
  .openapi({
    description:
      'A type indicating who or what last touched this object. `dashboard`, `link`, and `api` indicate the originating surface; `system` indicates Plaid. `retro` indicates a screening created retroactively via a bulk screening creation.',
  })
  .openapi('Source')

