const ProgramArchivedSchema = z
  .boolean()
  .openapi({
    example: false,
    title: 'Archived',
    description:
      'Archived programs are read-only and cannot screen new customers nor participate in ongoing monitoring.',
  })
  .openapi('ProgramArchived')

const EntityWatchlistProgramSchema = z
  .looseObject({
    id: EntityWatchlistProgramIDSchema,
    created_at: TimestampSchema,
    is_rescanning_enabled: z
      .boolean()
      .openapi({
        description:
          'Indicator specifying whether the program is enabled and will perform daily rescans.',
        example: true,
      }),
    lists_enabled: z
      .array(EntityWatchlistCodeSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description: 'Watchlists enabled for the associated program',
        example: ['EU_CON'],
      }),
    name: EntityWatchlistScreeningProgramNameSchema,
    name_sensitivity: ProgramNameSensitivitySchema,
    audit_trail: WatchlistScreeningAuditTrailSchema,
    is_archived: ProgramArchivedSchema,
  })
  .openapi({
    description:
      'A program that configures the active lists, search parameters, and other behavior for initial and ongoing screening of entities.',
    title: 'EntityWatchlistProgram',
    required: [
      'id',
      'created_at',
      'is_rescanning_enabled',
      'lists_enabled',
      'name',
      'name_sensitivity',
      'audit_trail',
      'is_archived',
    ],
  })
  .openapi('EntityWatchlistProgram')

