const IdentityVerificationStepStatusSchema = z
  .enum([
    'success',
    'active',
    'failed',
    'waiting_for_prerequisite',
    'not_applicable',
    'skipped',
    'expired',
    'canceled',
    'pending_review',
    'manually_approved',
    'manually_rejected',
  ])
  .openapi({
    example: 'success',
    title: 'IdentityVerificationStepStatus',
    description: 'The status of a step in the Identity Verification process.',
  })
  .openapi('IdentityVerificationStepStatus')

const IdentityVerificationStepSummarySchema = z
  .looseObject({
    accept_tos: IdentityVerificationStepStatusSchema,
    verify_sms: IdentityVerificationStepStatusSchema,
    kyc_check: IdentityVerificationStepStatusSchema,
    documentary_verification: IdentityVerificationStepStatusSchema,
    selfie_check: IdentityVerificationStepStatusSchema,
    watchlist_screening: IdentityVerificationStepStatusSchema,
    risk_check: IdentityVerificationStepStatusSchema,
  })
  .openapi({
    description:
      "Each step will be one of the following values:\n\n\n`active` - This step is the user's current step. They are either in the process of completing this step, or they recently closed their Identity Verification attempt while in the middle of this step. Only one step will be marked as `active` at any given point.\n\n`success` - The Identity Verification attempt has completed this step.\n\n`failed` - The user failed this step. This can either cause the user to fail the session as a whole, or cause them to fall back to another step depending on how the Identity Verification template is configured. A failed step does not imply a failed session.\n\n`waiting_for_prerequisite` - The user needs to complete another step first, before they progress to this step. This step may never run, depending on if the user fails an earlier step or if the step is only run as a fallback.\n\n`not_applicable` - This step will not be run for this session.\n\n`skipped` - This step was skipped, for example because the retry instructions that created this Identity Verification attempt specified that it should be skipped, because your template configuration skips it, or, for `accept_tos`, because `gave_consent` was `true`.\n\n`expired` - This step had not yet been completed when the Identity Verification attempt as a whole expired.\n\n`canceled` - The Identity Verification attempt was canceled before the user completed this step.\n\n`pending_review` - The Identity Verification attempt template was configured to perform a screening that had one or more hits needing review.\n\n`manually_approved` - The step was manually overridden to pass by a team member in the dashboard.\n\n`manually_rejected` - The step was manually overridden to fail by a team member in the dashboard.",
    required: [
      'accept_tos',
      'verify_sms',
      'kyc_check',
      'documentary_verification',
      'selfie_check',
      'watchlist_screening',
      'risk_check',
    ],
  })
  .openapi('IdentityVerificationStepSummary')

