const IndividualWatchlistScreeningProgramNameSchema = z
  .string()
  .openapi({
    title: 'IndividualWatchlistScreeningProgramName',
    example: 'Sample Program',
    description:
      'A name for the program to define its purpose. For example, "High Risk Individuals", "US Cardholders", or "Applicants".',
  })
  .openapi('IndividualWatchlistScreeningProgramName')

const IndividualWatchlistProgramSchema = z
  .looseObject({
    id: WatchlistProgramIDSchema,
    created_at: TimestampSchema,
    is_rescanning_enabled: z
      .boolean()
      .openapi({
        description:
          'Indicator specifying whether the program is enabled and will perform daily rescans.',
        example: true,
      }),
    lists_enabled: z
      .array(IndividualWatchlistCodeSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description: 'Watchlists enabled for the associated program',
        example: ['US_SDN'],
      }),
    name: IndividualWatchlistScreeningProgramNameSchema,
    name_sensitivity: ProgramNameSensitivitySchema,
    audit_trail: WatchlistScreeningAuditTrailSchema,
    is_archived: ProgramArchivedSchema,
  })
  .openapi({
    description:
      'A program that configures the active lists, search parameters, and other behavior for initial and ongoing screening of individuals.',
    title: 'IndividualWatchlistProgram',
    required: [
      'id',
      'created_at',
      'is_rescanning_enabled',
      'lists_enabled',
      'name',
      'name_sensitivity',
      'audit_trail',
      'is_archived',
    ],
  })
  .openapi('IndividualWatchlistProgram')

