const CraReportGetBaseReportAccountBalancesSchema = z
  .looseObject({
    available: z
      .float64()
      .nullable()
      .openapi({
        description:
          'The amount of funds available to be withdrawn from the account, as determined by the financial institution.\n\nFor `credit`-type accounts, the `available` balance typically equals the `limit` less the `current` balance, less any pending outflows plus any pending inflows.\n\nFor `depository`-type accounts, the `available` balance typically equals the `current` balance less any pending outflows plus any pending inflows, and does not include the overdraft limit.\n\nFor `investment`-type accounts, the `available` balance is the total cash available to withdraw as presented by the institution.\n\n`null` if the institution does not provide an `available` balance. If `current` is `null`, this field is guaranteed not to be `null`.',
      }),
    current: z
      .float64()
      .nullable()
      .openapi({
        description:
          'The total amount of funds in or owed by the account.\n\nFor `credit`-type accounts, a positive balance indicates the amount owed; a negative amount indicates the lender owing the account holder.\n\nFor `loan`-type accounts, the current balance is the principal remaining on the loan.\n\nFor `investment`-type accounts, the current balance is the total value of assets as presented by the institution.\n\nIf `available` is `null`, this field is guaranteed not to be `null`.',
      }),
    limit: z
      .float64()
      .nullable()
      .openapi({
        description:
          'For `credit`-type accounts, the credit limit.\n\nFor `depository`-type accounts, the pre-arranged overdraft limit.\n\nThis field is typically only available for `credit`-type accounts.',
      }),
    iso_currency_code: CreditIsoCurrencyCodeSchema,
    unofficial_currency_code: CreditUnofficialCurrencyCodeSchema,
    average_balance: z
      .float64()
      .nullable()
      .openapi({
        description:
          'The average historical balance over the time range of the report. `null` if it could not be computed.',
      }),
    most_recent_thirty_day_average_balance: z
      .float64()
      .nullable()
      .openapi({
        description:
          'The average historical balance over the most recent 30 days. `null` if it could not be computed.',
      }),
    average_monthly_balances: z
      .array(CraReportGetBaseReportAverageMonthlyBalanceSchema)
      .openapi({
        description:
          'The average historical balance for each calendar month. Empty if it could not be computed.',
      }),
  })
  .openapi({
    title: 'CraReportGetBaseReportAccountBalances',
    description: 'The balances of an account in a Base Report.',
    required: [
      'available',
      'current',
      'limit',
      'iso_currency_code',
      'unofficial_currency_code',
      'average_balance',
      'most_recent_thirty_day_average_balance',
      'average_monthly_balances',
    ],
  })
  .openapi('CraReportGetBaseReportAccountBalances')

