const SignalScheduleDefaultPaymentMethodSchema = z
  .enum(['SAME_DAY_ACH', 'STANDARD_ACH', 'MULTIPLE_PAYMENT_METHODS'])
  .openapi({
    title: 'SignalScheduleDefaultPaymentMethod',
    description:
      'The payment method specified in the `default_payment_method` field directly impacts the timing recommendations provided by the API for submitting the debit entry to your processor or ODFI. If unspecified, defaults to `STANDARD_ACH`.\n\n`SAME_DAY_ACH`: Same Day ACH (as defined by Nacha). The API assumes the settlement will occur on the same business day as submission. Note: The actual cutoff time can vary depending on your payment processor or ODFI. Nacha has established three processing windows for Same Day ACH (Eastern Time): 10:30 AM, 2:45 PM, and 4:45 PM.\n\n`STANDARD_ACH`: Standard ACH (as defined by Nacha), typically settled one to three business days after submission.\n\n`MULTIPLE_PAYMENT_METHODS`: Indicates that there is no default debit rail or multiple payment methods are available, and the transaction could use any of them based on customer policy or availability.',
  })
  .openapi('SignalScheduleDefaultPaymentMethod')

const SignalScheduleRequestSchema = z
  .object({
    client_id: APIClientIDSchema.exactOptional(),
    secret: APISecretSchema.exactOptional(),
    access_token: AccessTokenSchema,
    account_id: z
      .string()
      .openapi({
        description:
          'The Plaid `account_id` of the account that is the funding source for the proposed transaction. The `account_id` is returned in the `/accounts/get` endpoint as well as the [`onSuccess`](https://plaid.com/docs/link/ios/#link-ios-onsuccess-linkSuccess-metadata-accounts-id) callback metadata.\n\nThis will return an [`INVALID_ACCOUNT_ID`](https://plaid.com/docs/errors/invalid-input/#invalid_account_id) error if the account has been removed at the bank or if the `account_id` is no longer valid.',
      }),
    client_transaction_id: z
      .string()
      .min(1)
      .max(36)
      .openapi({
        description:
          'The unique ID that you would like to use to refer to this transaction. For your convenience mapping your internal data, you could use your internal ID/identifier for this transaction. The max length for this field is 36 characters.',
      }),
    amount: z.float64().openapi({ description: 'The transaction amount, in USD (e.g. `102.05`)' }),
    default_payment_method: SignalScheduleDefaultPaymentMethodSchema.exactOptional(),
  })
  .openapi({
    title: 'SignalScheduleRequest',
    description: 'SignalScheduleRequest defines the request schema for `/signal/schedule`',
    required: ['access_token', 'account_id', 'client_transaction_id', 'amount'],
  })
  .openapi('SignalScheduleRequest')

const RecommendationStringSchema = z
