export const postCreditAuditCopyTokenUpdateRoute = createRoute({
  method: 'post',
  path: '/credit/audit_copy_token/update',
  tags: ['plaid'],
  summary: 'Update an Audit Copy Token',
  description:
    'The `/credit/audit_copy_token/update` endpoint updates an existing Audit Copy Token by adding the report tokens in the `report_tokens` field to the `audit_copy_token`. If the Audit Copy Token already contains a report of a certain type, it will be replaced with the token provided in the `report_tokens` field.',
  externalDocs: { url: '/none/' },
  operationId: 'creditAuditCopyTokenUpdate',
  request: {
    body: {
      content: { 'application/json': { schema: CreditAuditCopyTokenUpdateRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: CreditAuditCopyTokenUpdateResponseSchema,
          examples: { 'example-1': { value: { request_id: 'eYupqX1mZkEuQRx', updated: true } } },
        },
      },
    },
    default: {
      description: 'Error response',
      content: { 'application/json': { schema: PlaidErrorSchema } },
    },
  },
})

