      description: 'OK',
      content: {
        'application/json': {
          schema: ItemPublicTokenCreateResponseSchema,
          examples: {
            'example-1': {
              value: {
                public_token: 'public-sandbox-b0e2c4ee-a763-4df5-bfe9-46a46bce993d',
                request_id: 'Aim3b',
              },
            },
          },
        },
      },
