export const postUserProductsTerminateRoute = createRoute({
  method: 'post',
  path: '/user/products/terminate',
  tags: ['plaid'],
  summary: 'Terminate products for a user',
  description:
    'Terminates Financial Management, Plaid Protect, and Servicing products associated with a `user_id`. Use this endpoint when offboarding a user or ending their subscriptions. Item access tokens are not required.\n\nFor Financial Management products, including Transactions, Liabilities, and Investments, this endpoint removes each associated Item that contains one of these products. Removal makes the Item inaccessible, initiates deletion of its product data, and terminates its per-Item subscription billing. The entire Item is removed, including access to any other products on that Item. To connect the accounts again, the user must complete Link to create a new Item.\n\nIf the user has at least one associated Item and every associated Item contains a Financial Management product, this endpoint also removes the associated Plaid user. The removed `user_id` can no longer be used to access the user.\n\nFor Plaid Protect, this endpoint terminates Protect products. For Servicing, it cancels the subscription and preserves CRA Items and historical data for future report requests.',
  externalDocs: { url: '/api/users/#userproductsterminate' },
  operationId: 'userProductsTerminate',
  request: {
    body: {
      content: {
        'application/json': {
          schema: UserProductsTerminateRequestSchema,
          examples: {
            'example-1': {
              value: {
                user_id: 'usr_8c3ZbDBYjaqUXZ',
                reason_code: 'CONSUMER_ACCOUNT_CLOSED',
                reason_note: 'User closed account with client.',
              },
            },
            'example-2': {
              value: {
                user_id: 'usr_8c3ZbDBYjaqUXZ',
                reason_code: 'CONSUMER_LOAN_PAID_OFF',
                reason_note: 'Consumer loan has been paid in full.',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: UserProductsTerminateResponseSchema,
          examples: { 'example-1': { value: { request_id: 'TxlxEcCmP9HTTT' } } },
        },
      },
    },
    default: {
      description: 'Error response',
      content: { 'application/json': { schema: PlaidErrorSchema } },
    },
  },
})

