export const postIncomeVerificationDocumentsDownloadRoute = createRoute({
  method: 'post',
  path: '/income/verification/documents/download',
  tags: ['plaid'],
  summary: '(Deprecated) Download the original documents used for income verification',
  description:
    '`/income/verification/documents/download` provides the ability to download the source documents associated with the verification.\n\nIf Document Income was used, the documents will be those the user provided in Link. For Payroll Income, the most recent files available for download from the payroll provider will be available from this endpoint.\n\nThe response to `/income/verification/documents/download` is a ZIP file in binary data. If a `document_id` is passed, a single document will be contained in this file.\nIf not, the response will contain all documents associated with the verification.\n\nThe `request_id` is returned in the `Plaid-Request-ID` header.',
  externalDocs: { url: '/api/products/income/#incomeverificationdocumentsdownload' },
  operationId: 'incomeVerificationDocumentsDownload',
  request: {
    body: {
      content: { 'application/json': { schema: IncomeVerificationDocumentsDownloadRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'A ZIP file containing source documents(s) used as the basis for income verification.',
      content: {
        'application/zip': { schema: z.file().openapi({ type: 'string', format: 'binary' }) },
      },
    },
    default: {
      description: 'Error response',
      content: { 'application/json': { schema: PlaidErrorSchema } },
    },
  },
  deprecated: true,
})

