export const postCreditRelayPdfGetRoute = createRoute({
  method: 'post',
  path: '/credit/relay/pdf/get',
  tags: ['plaid'],
  summary: 'Retrieve the PDF reports associated with a relay token that was shared with you (beta)',
  description:
    '`/credit/relay/pdf/get` allows third parties to receive a PDF report that was shared with them, using a `relay_token` that was created by the report owner.\n\nThe `/credit/relay/pdf/get` endpoint retrieves the Asset Report in PDF format. Before calling `/credit/relay/pdf/get`, you must first create the Asset Report using `/credit/relay/create` and then wait for the [`PRODUCT_READY`](https://plaid.com/docs/api/products/assets/#product_ready) webhook to fire, indicating that the Report is ready to be retrieved.\n\nThe response to `/credit/relay/pdf/get` is the PDF binary data. The `request_id` is returned in the `Plaid-Request-ID` header.\n\n[View a sample PDF Asset Report](https://plaid.com/documents/sample-asset-report.pdf).',
  externalDocs: { url: '/api/products/assets/#creditrelaypdfget' },
  operationId: 'creditRelayPdfGet',
  request: {
    body: {
      content: { 'application/json': { schema: CreditRelayPDFGetRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'A PDF of the Asset Report',
      content: { 'application/pdf': { schema: CreditRelayPDFGetResponseSchema } },
    },
    default: {
      description: 'Error response',
      content: { 'application/json': { schema: PlaidErrorSchema } },
    },
  },
})

