export const postSignalEvaluateRoute = createRoute({
  method: 'post',
  path: '/signal/evaluate',
  tags: ['plaid'],
  summary: 'Evaluate a planned ACH transaction',
  description:
    'Use `/signal/evaluate` to evaluate a planned ACH transaction to get a return risk assessment and additional risk signals.\n\nBefore using `/signal/evaluate`, you must first [create a ruleset](https://plaid.com/docs/signal/signal-rules/) in the Dashboard under [**Signal->Rules**](https://dashboard.plaid.com/signal/risk-profiles).\n\n`/signal/evaluate` can be used with either Signal Transaction Scores or the Balance product. Which product is used will be determined by the `ruleset_key` that you provide. For more details, see [Signal Rules](https://plaid.com/docs/signal/signal-rules/).\n\nNote: This request may have higher latency when using a Balance-only ruleset. This is because Plaid must communicate directly with the institution to request data. Balance-only rulesets may have latency of up to 30 seconds or more; if you encounter errors, you may find it necessary to adjust your timeout period when making requests.',
  externalDocs: { url: '/api/products/signal#signalevaluate' },
  operationId: 'signalEvaluate',
  request: {
    body: {
      content: { 'application/json': { schema: SignalEvaluateRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: SignalEvaluateResponseSchema,
          examples: {
            'example-1': {
              value: {
                scores: {
                  customer_initiated_return_risk: { score: 9 },
                  bank_initiated_return_risk: { score: 82 },
                },
                core_attributes: { available_balance: 2200, current_balance: 2000 },
                ruleset: {
                  ruleset_key: 'onboarding_flow',
                  result: 'REROUTE',
                  triggered_rule_details: {
                    internal_note:
                      'Rerouting customer to different payment method, since bank risk score is too high',
                  },
                },
                warnings: [],
                request_id: 'mdqfuVxeoza6mhu',
              },
            },
          },
        },
      },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: PlaidErrorSchema } },
    },
  },
})

